<template><section class="route-page inbound-orders-page"><header class="content-header inbound-orders-page__header"><div><h1>{{ $route.meta.title }}</h1><p>查询出库记录、审批状态与出库物品。</p></div><button v-if="canCreate" class="primary-button" type="button" @click="router.push({name:'outbound'})">新建出库</button></header><section class="inbound-orders-workspace" aria-label="出库单列表"><div class="inbound-orders-toolbar"><SearchField v-model="searchInput" label="搜索出库单" name="outbound_order_search" placeholder="搜索单号、去向、物品或批次" hide-label @search="applySearch"/><div class="inbound-orders-toolbar__meta"><span class="inbound-orders-count">{{total}} 条</span><div class="inbound-orders-toolbar__actions"><button class="icon-button inbound-orders-toolbar__filter" type="button" title="筛选出库单" :aria-expanded="filterOpen" @click="filterOpen=true"><svg viewBox="0 0 24 24"><path d="M4 6h16M7 12h10M10 18h4"/></svg><span v-if="filterCount">{{filterCount}}</span></button><button class="icon-button inbound-orders-toolbar__refresh" type="button" title="刷新出库单" :disabled="pending" @click="loadFirst"><svg viewBox="0 0 24 24"><path d="M20 7v5h-5"/><path d="M18.2 16a7 7 0 1 1 .8-7l1 3"/></svg></button></div></div></div><div ref="root" class="inbound-orders-results" :aria-busy="pending"><section v-if="error&&!loaded" class="inbound-orders-state inbound-orders-state--error"><strong>无法加载出库单</strong><span>{{error}}</span><button class="secondary-button" @click="loadFirst">重试</button></section><section v-else-if="!orders.length&&loaded" class="inbound-orders-state"><strong>{{hasFilters?'没有符合筛选条件的出库单':'暂无出库单'}}</strong><button v-if="hasFilters" class="text-button" @click="clear">清除筛选</button></section><template v-else><div class="inbound-orders-table" role="table"><div class="inbound-orders-table__head" role="row"><span>单据与去向</span><span>出库物品</span><span>状态与操作</span></div><article v-for="o in orders" :key="o.id" class="inbound-orders-table__row" role="row" tabindex="0" @click="open(o)" @keydown.enter="open(o)"><div><strong>出库单 #{{o.id}}</strong><span>{{o.destination}}</span><time>{{date(o.created_at)}}</time></div><div><div class="inbound-order-item-summary"><AuthenticatedImage :file-id="o.items[0].item_image_file_id" :alt="`${o.items[0].item_name} 主图`" :size="34"/><div><strong>{{o.items[0].item_name}}</strong><small>{{o.items[0].item_sku}} · {{o.items[0].quantity}} {{o.items[0].item_unit}}{{o.items.length>1?` · 等 ${o.items.length} 项`:''}}</small></div></div><span>{{o.items.length}} 条明细</span></div><div class="inbound-orders-table__decision"><span class="inbound-status" :class="`inbound-status--${o.status}`">{{label(o.status)}}</span><time v-if="statusTime(o)">{{date(statusTime(o)!)}}</time><button class="icon-button" type="button" title="查看出库单详情" @click.stop="open(o)"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8"/><path d="M12 11v5M12 8h.01"/></svg></button></div></article></div><div ref="sentinel" class="inbound-orders-load-more"><span v-if="moreLoading">正在加载更多出库单…</span><button v-else-if="moreError" class="secondary-button" @click="next">加载失败，点击重试</button><span v-else-if="more">继续向下滚动加载</span><span v-else>已加载全部 {{total}} 条出库单</span></div></template></div></section><OutboundOrderFiltersDialog :open="filterOpen" :value="filterValue" @close="filterOpen=false" @apply="apply"/><ModalDialog :open="selected!==null" wide :title="selected?`出库单 #${selected.id}`:''" @close="selected=null"><template #context><div v-if="selected" class="dialog-account-context"><span>{{label(selected.status)}}</span><strong>{{selected.destination}}</strong></div></template><template v-if="selected"><dl class="inbound-detail-summary"><div><dt>创建时间</dt><dd>{{date(selected.created_at)}}</dd></div><div><dt>状态</dt><dd>{{statusDescription(selected)}}</dd></div><div><dt>备注</dt><dd>{{selected.notes||'暂无备注'}}</dd></div></dl><section class="inbound-detail-items"><h3>出库物品 <span>{{selected.items.length}} 条</span></h3><article v-for="i in selected.items" :key="i.id"><header class="inbound-detail-item__header"><AuthenticatedImage :file-id="i.item_image_file_id" :alt="`${i.item_name} 主图`" :size="52" previewable/><div><strong>{{i.item_name}}</strong><small>{{i.item_sku}} · {{i.item_unit}} · 物品 #{{i.item_id}}</small></div><span>{{i.quantity}} {{i.item_unit}}</span></header><dl><div><dt>库位</dt><dd>{{i.location_name||'全部库位'}}</dd></div><div><dt>扣减方式</dt><dd>{{i.batch_id?`指定批次 #${i.batch_id}`:'按 FIFO 分配（审批时确认）'}}</dd></div></dl></article></section></template><template #actions><button class="secondary-button" @click="selected=null">关闭</button><button v-if="canApprove&&selected?.status==='pending'" class="primary-button" @click="router.push({name:'outbound-approvals'})">前往出库审批</button></template></ModalDialog></section></template>
<script setup lang="ts">import{computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{getOutboundOrder,listOutboundOrders,type OutboundOrderResponse,type OutboundOrderStatus}from'../api/outboundOrders';import{hasPermission,stockPermissions}from'../auth/permissions';import{authSession}from'../auth/session';import AuthenticatedImage from'../components/attributes/AuthenticatedImage.vue';import ModalDialog from'../components/ModalDialog.vue';import OutboundOrderFiltersDialog,{type OutboundOrderFilterValue}from'../components/outbound/OutboundOrderFiltersDialog.vue';import SearchField from'../components/SearchField.vue';import'./InboundOrdersPage.scss';const route=useRoute(),router=useRouter(),orders=ref<OutboundOrderResponse[]>([]),total=ref(0),pages=ref(0),loaded=ref(false),loading=ref(false),moreLoading=ref(false),error=ref(''),moreError=ref(''),selected=ref<OutboundOrderResponse|null>(null),searchInput=ref(''),from=ref(''),to=ref(''),filterOpen=ref(false),root=ref<HTMLElement|null>(null),sentinel=ref<HTMLElement|null>(null),state=reactive({page:1,status:'' as OutboundOrderStatus|'',search:''});let ctrl:AbortController|null=null,observer:IntersectionObserver|null=null;const pending=computed(()=>loading.value||moreLoading.value),more=computed(()=>state.page<pages.value),canCreate=computed(()=>hasPermission(authSession.value?.user.permissions,stockPermissions.outboundCreate)),canApprove=computed(()=>hasPermission(authSession.value?.user.permissions,stockPermissions.outboundApprove)),hasFilters=computed(()=>!!(state.search||state.status||from.value||to.value)),filterCount=computed(()=>[state.status,from.value,to.value].filter(Boolean).length),filterValue=computed<OutboundOrderFilterValue>(()=>({status:state.status,dateFrom:local(from.value),dateTo:local(to.value)}));watch(()=>route.fullPath,()=>{state.status=isStatus(route.query.status)?route.query.status:'';state.search=typeof route.query.search==='string'?route.query.search:'';searchInput.value=state.search;from.value=iso(route.query.date_from);to.value=iso(route.query.date_to);void loadFirst()},{immediate:true});onMounted(()=>{observer=new IntersectionObserver(e=>{if(e.some(x=>x.isIntersecting))void next()},{root:root.value,rootMargin:'240px 0px'});watch(sentinel,()=>{if(sentinel.value){observer?.disconnect();observer?.observe(sentinel.value)}},{immediate:true})});onBeforeUnmount(()=>{ctrl?.abort();observer?.disconnect()});async function load(p=1,append=false){ctrl?.abort();const c=new AbortController();ctrl=c;append?moreLoading.value=true:loading.value=true;append?moreError.value='':error.value='';try{const r=await listOutboundOrders({page:p,page_size:50,search:state.search||undefined,status:state.status||undefined,date_from:from.value||undefined,date_to:to.value||undefined},c.signal);if(ctrl!==c)return;orders.value=append?[...orders.value,...r.items.filter(i=>!orders.value.some(x=>x.id===i.id))]:r.items;total.value=r.total;pages.value=r.total_pages;state.page=r.page;loaded.value=true}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))append?moreError.value='加载更多失败':error.value='请检查服务连接后重试'}finally{if(ctrl===c){ctrl=null;loading.value=false;moreLoading.value=false;void nextTick()}}}function loadFirst(){return load()}function next(){if(!pending.value&&more.value)return load(state.page+1,true)}function query(v:Record<string,string|undefined>){void router.replace({query:v})}function applySearch(v:string){query({search:v.trim()||undefined,status:state.status||undefined,date_from:from.value||undefined,date_to:to.value||undefined})}function apply(v:OutboundOrderFilterValue){const a=toIso(v.dateFrom),b=toIso(v.dateTo);if((v.dateFrom&&!a)||(v.dateTo&&!b)||(a&&b&&a>b)){error.value='请输入有效的创建时间范围';return}filterOpen.value=false;query({search:state.search||undefined,status:v.status||undefined,date_from:a||undefined,date_to:b||undefined})}function clear(){query({})}async function open(o:OutboundOrderResponse){selected.value=o;try{selected.value=await getOutboundOrder(o.id)}catch{}}function isStatus(v:unknown):v is OutboundOrderStatus{return v==='pending'||v==='approved'||v==='rejected'}function iso(v:unknown){return typeof v==='string'&&!Number.isNaN(new Date(v).getTime())?new Date(v).toISOString():''}function local(v:string){if(!v)return'';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,19)}function toIso(v:string){return v&&!Number.isNaN(new Date(v).getTime())?new Date(v).toISOString():''}function label(s:OutboundOrderStatus){return{pending:'待审批',approved:'已出库',rejected:'已拒绝'}[s]}function statusTime(o:OutboundOrderResponse){return o.status==='approved'?o.approved_at:o.status==='rejected'?o.rejected_at:null}function statusDescription(o:OutboundOrderResponse){return o.status==='pending'?'等待审批，库存未扣减':o.status==='approved'?`已于 ${date(o.approved_at||'')} 出库，库存已扣减`:'已拒绝，库存未扣减'}function date(v:string){const d=new Date(v);return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(d)}</script>
